CREATE TABLE IF NOT EXISTS document_applications (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, type TEXT NOT NULL CHECK(type IN ('national_id','residency','passport')), full_name TEXT NOT NULL, nationality TEXT NOT NULL, birth_date TEXT, issuer TEXT NOT NULL, expires_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), document_id TEXT REFERENCES documents(id), decided_by TEXT REFERENCES users(id), decided_at TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
